"""Stage the existing SWSS payload with its original Debian package helpers."""
import argparse
import gzip
import json
import os
from pathlib import Path
import shutil
import subprocess
import tempfile


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    for name in ['data', 'source', 'tar', 'fixperms', 'installdeb', 'output_data', 'receipt']:
        parser.add_argument('--' + name.replace('_', '-'), type=Path, required=True)
    parser.add_argument('--package', choices=['swss', 'swss-dbg'], required=True)
    parser.add_argument('--architecture', required=True)
    parser.add_argument('--conffiles', type=Path)
    args = parser.parse_args()
    paths = {name: getattr(args, name).absolute() for name in ['data', 'source', 'tar', 'fixperms', 'installdeb', 'output_data', 'receipt']}
    conffiles = args.conffiles.absolute() if args.conffiles else None
    with tempfile.TemporaryDirectory(prefix='swss-debian-') as directory:
        work = Path(directory)
        debian = work / 'debian'
        package = debian / args.package
        package.mkdir(parents=True)
        for name in ['control', 'changelog', 'compat']:
            shutil.copyfile(paths['source'] / name, debian / name)
        # dist:swss_pkg already includes Automake's direct installation and the
        # supplemental swss.install entries. The existing CI audits that parity.
        subprocess.run([str(paths['tar']), '-xf', str(paths['data']), '-C', str(package)], check=True)
        doc = package / 'usr/share/doc' / args.package
        doc.mkdir(parents=True)
        (doc / 'changelog.gz').write_bytes(gzip.compress((debian / 'changelog').read_bytes(), mtime=0))
        subprocess.run([str(paths['fixperms']), '-p' + args.package], cwd=work,
                       env=dict(os.environ, DEB_HOST_ARCH=args.architecture,
                                DEB_RULES_REQUIRES_ROOT='no'), check=True)
        subprocess.run([str(paths['installdeb']), '-p' + args.package], cwd=work,
                       env=dict(os.environ, DEB_HOST_ARCH=args.architecture), check=True)
        controls = package / 'DEBIAN'
        actual = {p.name for p in controls.iterdir()} if controls.exists() else set()
        expected = {'conffiles'} if conffiles else set()
        if actual != expected:
            raise ValueError(f'Unexpected helper outputs: {actual}; expected {expected}')
        if conffiles:
            shutil.copyfile(controls / 'conffiles', conffiles)
        if controls.exists():
            shutil.rmtree(controls)
        members = [package] + sorted(package.rglob('*'))
        for path in members:
            os.utime(path, (0, 0), follow_symlinks=False)
        manifest = work / 'members.txt'
        manifest.write_text(''.join(str(path.relative_to(package)) + '\n' for path in members))
        subprocess.run([str(paths['tar']), '--create', '--format=gnutar', '--uid=0', '--gid=0',
                        '--numeric-owner', '--no-recursion', '--file', str(paths['output_data']),
                        '-C', str(package), '-T', str(manifest)], check=True)
        paths['receipt'].write_text(json.dumps({
            '_generated': 'AUTO-GENERATED by debian/stage.py. DO NOT EDIT MANUALLY.',
            'package': args.package, 'architecture': args.architecture,
            'control_files': sorted(expected), 'status': 'passed',
        }, indent=2) + '\n')


if __name__ == '__main__':
    main()
